def chunk(xs, n, overlap=0):
    if n < 1:
        raise ValueError("n must be >= 1")
    if not 0 <= overlap < n:
        raise ValueError("overlap must be in [0, n)")
    step = n - overlap
    out = []
    for i in range(0, len(xs), step):
        out.append(xs[i:i + n])
        if i + n >= len(xs):
            break
    return out

