    m.get_or_create({}, "b", lambda k: 3, lock=lk)
    assert not lk.locked()
    def boom(k):
        raise KeyError(k)
    try:
        m.get_or_create({}, "c", boom, lock=lk)
    except KeyError:
        pass
    assert not lk.locked()

