def moving_avg(xs, k):
    if k <= 0:
        raise ValueError("k must be positive")
    if k > len(xs):
        return []
    total = sum(xs[:k])
    out = [total / k]
    for i in range(k, len(xs)):
        total += xs[i] - xs[i - k]
        out.append(total / k)
    return out

