import resilience as m
from _rt import needs

def test_exc_class():
    assert issubclass(m.TransientError, Exception)

def test_succeeds_after_transient():
    needs(m, "retry_call")
    calls = []
    def fn():
        calls.append(1)
        if len(calls) < 3:
            raise m.TransientError("flaky")
        return "ok"
    assert m.retry_call(fn, attempts=3) == "ok"

def test_gives_up_with_last_error():
    needs(m, "retry_call")
    def fn():
        raise m.TransientError("still down")
    try:
        m.retry_call(fn, attempts=2)
    except m.TransientError as e:
        assert str(e) == "still down"
        return
    raise AssertionError

def test_permanent_error_not_retried():
    needs(m, "retry_call")
    calls = []
    def fn():
        calls.append(1)
        raise ValueError("bad input")
    try:
        m.retry_call(fn, attempts=3)
    except ValueError:
        assert len(calls) == 1
        return
    raise AssertionError

