import netcheck as m
from _rt import needs

class Rec:
    def __init__(self):
        self.calls = []
    def __call__(self, cmd, **kw):
        self.calls.append((cmd, kw))
        return "ok"

def test_regex():
    assert m.HOST_RE.fullmatch("example.com")

def test_argv_list_no_shell():
    needs(m, "ping_host")
    r = Rec()
    assert m.ping_host("example.com", runner=r) == "ok"
    cmd, kw = r.calls[0]
    assert cmd == ["ping", "-c", "1", "example.com"] and not kw.get("shell")

def test_rejects_metacharacters():
    needs(m, "ping_host")
    r = Rec()
    for bad in ("a; rm -rf /", "x && id", "$(id)", ""):
        try:
            m.ping_host(bad, runner=r)
        except ValueError:
            continue
        raise AssertionError(bad)
    assert not r.calls

def test_rejects_option_injection():
    needs(m, "ping_host")
    r = Rec()
    try:
        m.ping_host("-f", runner=r)
    except ValueError:
        assert not r.calls
        return
    raise AssertionError

