    needs(m, "with_connection")
    c = Conn()
    def boom(conn):
        raise RuntimeError("x")
    try:
        m.with_connection(boom, factory=lambda: c)
    except RuntimeError:
        pass
    else:
        raise AssertionError
    assert c.closed == 1

